
(function(root){'use strict';let layer,shown;const R=root.Rooftop201;
function create(){if(layer)return;const host=document.querySelector('#cabinet');if(!host)return;layer=document.createElement('div');layer.id='rooftopChoice201';layer.className='destination-layer183';layer.hidden=true;layer.setAttribute('role','dialog');layer.setAttribute('aria-modal','true');layer.setAttribute('aria-labelledby','roofTitle201');layer.innerHTML='<div class="destination-card183"><p class="eyebrow">FINANCIAL DISTRICT COMPLETE · HELICOPTER SECURED</p><h2 id="roofTitle201">CHOOSE YOUR<br><span>NEXT DESTINATION.</span></h2><p id="roofCopy201" class="destination-copy183">Leroy is down. Two leads remain.</p><div class="destination-options183">'+R.choices.map((x,i)=>'<button type="button" data-roof201="'+x.id+'"><small>0'+(i+1)+' / FLIGHT PLAN</small><strong>'+x.name+'</strong><span>'+x.detail+'</span><b>TRAVEL NEXT →</b></button>').join('')+'</div><p class="destination-help183">← / → or D-pad: choose · Enter / PS5 ×: confirm<br>Mouse or touch: choose your next destination.</p></div>';host.append(layer);for(const b of layer.querySelectorAll('button')){b.onclick=()=>R.choose(game,b.dataset.roof201);b.onfocus=()=>{if(game.rooftop201?.phase==='choice')game.rooftop201.selected=R.choices.findIndex(x=>x.id===b.dataset.roof201);};}}
function sync(g){create();if(!layer)return;const q=g.rooftop201;layer.hidden=!R.menu(g);if(layer.hidden){shown=null;return;}const fresh=shown!==q;for(const[i,b]of Array.from(layer.querySelectorAll('button')).entries()){b.classList.toggle('selected183',q.selected===i);b.setAttribute('aria-pressed',String(q.selected===i));if(fresh&&q.selected===i)b.focus({preventScroll:true});}if(fresh){shown=q;paused=false;pauseLayer.hidden=true;overlay.hidden=true;overlay.style.display='none';clearKeys();}if(q.phase==='complete'){const chosen=R.choices[q.selected];layer.querySelector('#roofTitle201').innerHTML='NEXT STOP:<br><span>'+chosen.name+'.</span>';layer.querySelector('#roofCopy201').textContent='Flight plan confirmed. To be continued at '+chosen.name.toLowerCase()+'.';status.textContent='FINANCIAL DISTRICT COMPLETE · NEXT: '+chosen.name;if(q.saved201===chosen.id)return;q.saved201=chosen.id;try{localStorage.setItem('urban-fracture-next-lead201',JSON.stringify({destination:chosen.id,hero:g.player.type,score:g.score,environment:g.saveEnvironment156?.()}));}catch{}}else status.textContent='FINANCIAL DISTRICT COMPLETE · CHOOSE HOSPITAL OR FBI OFFICE';}
root.RooftopUI201={sync};
})(window);
